agent-librarian.code:
// Helps readers find books.
agent Librarian(tools: BookTools)
  prompt: string = "You help readers find books. Use the tools; never invent ids."

graph-summary.code:
// A summary of the assistant's answer.
@state(SummaryState)
graph Summary(librarian: Librarian)
  @start
  @next("end")
  ask(state: SummaryState) <string, string>
    { "answer": ~librarian.ask(state.question) }

graph-two-steps.code:
// A state ReviewState (text: string, draft: string, final: string) and a graph Review(librarian: Librarian): node draft (the first) sets draft to ~librarian.ask(state.text) and goes to polish; node polish sets final to ~librarian.ask("Shorten: ${state.draft}") and ends.
@state(ReviewState)
graph Review(librarian: Librarian)
  @start
  @next("polish")
  draft(state: ReviewState) <string, string>
    { "draft": ~librarian.ask(state.text) }

  @next("end")
  polish(state: ReviewState) <string, string>
    { "final": ~librarian.ask("Shorten: ${state.draft}") }

