feature-new-reader.code:
// file: components/reader/data/entities/reader.nuc
@entity("readers")
entity Reader()
  @primary(generated = true)
  id: int

  name: string
  email: string

// file: components/reader/domain/models/new_reader.nuc
model NewReader
  @minLength(2) name: string
  @email email: string

// file: components/reader/domain/usecases/create_reader.nuc
usecase CreateReader(readers: ReaderRepository)
  exec(input: NewReader) Result<Error, Reader>
    taken = ~readers.where({ "email": input.email }).exists()
    if taken
      return Err(Conflict("${input.email} is taken"))
    saved = ~readers.save(Reader(name = input.name, email = input.email))
    Ok(saved)

// file: components/reader/data/repositories/reader_repository.nuc
repository ReaderRepository
  save(reader: Reader) Result<Error, Reader>
    saved = ~reader.save(reader)
    Ok(saved)

usecase CreateReader(readers: ReaderRepository)
  exec(input: NewReader) Result<Error, Reader>
    saved = ~reader.save(Reader(name = input.name, email = input.email))
    Ok(saved)

// file: components/reader/reader_appcomponent.nuc
appcomponent ReadersAppComponent
  create() = CreateReader.exec

// file: components/reader/api/readers_controller.nuc
@controller("readers")
controller ReadersController(readers: ReadersAppComponent)
  @post()
  create(input: NewReader) Result<Error, Reader>
    ~readers.create(input)
    status = 201

